"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["21966"],{30799(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.peso_area_enem.grupo_curso_invalido","status":422,"titulo":"Grupo de curso fora do dom\xednio de grupos de \xe1rea do ENEM"},"descricao":{"codigo":"uniplus.configuracao.peso_area_enem.grupo_curso_invalido","requisitos":[],"oQueAconteceu":["O campo `grupoCurso` do cadastro de uma linha de pesos por \xe1rea do ENEM veio ausente ou com um c\xf3digo que n\xe3o \xe9 um dos quatro grupos de \xe1rea da Resolu\xe7\xe3o n\xba 805/2024/Consepe, da Unifesspa (Anexo I): `TECNOLOGICA`, `HUMANISTICA_I`, `HUMANISTICA_II` e `SAUDE_E_BIOLOGICAS`. O grupo \xe9 escolhido pelo c\xf3digo, sem acento e em mai\xfasculas, e o r\xf3tulo \xe9 sempre posto pelo sistema; o r\xf3tulo escrito por extenso n\xe3o serve como c\xf3digo. Os espa\xe7os nas pontas s\xe3o desconsiderados.","O grupo s\xf3 \xe9 enviado no cadastro: na atualiza\xe7\xe3o, a resolu\xe7\xe3o e o grupo da linha n\xe3o mudam. A recusa vem na lista `errors` da resposta, com `field` igual a `grupoCurso`, e a mensagem lista os c\xf3digos aceitos. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. \xc9 o mesmo dom\xednio fechado que o cadastro de curso confere (ver [grupo de \xe1rea do ENEM do curso inv\xe1lido](/erros/uniplus.configuracao.curso.grupo_area_enem_invalido))."],"comoResolver":["Envie um dos quatro c\xf3digos. Eles v\xeam, com o r\xf3tulo, de `GET /api/configuracao/vocabularios/grupos-area-enem`."],"ondeAparece":["Cadastro dos pesos por \xe1rea do ENEM"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Peso area enem"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);